from typing import Any, Dict, List
from datetime import datetime

def strip_data_url(s: Any) -> str | None:
    """Bỏ phần 'data:image/jpeg;base64,' và chỉ lấy phần base64 phía sau."""
    if not isinstance(s, str):
        return None
    parts = s.split(",", 1)
    return parts[1] if len(parts) > 1 else parts[0]

# Map tag → mô tả tiếng Việt với emoji
TAG_LABELS: Dict[str, str] = {
    "speed_violation": "⚡ Vượt quá tốc độ",
    "no_helmet":       "🪖 Không đội mũ bảo hiểm",
    "red_light":       "🔴 Vượt đèn đỏ",
}

UNKNOWN = "Không xác định"

out: List[Dict[str, Any]] = []

for item in items:
    json_data: Dict[str, Any] = item.get("json", {})
    body: Dict[str, Any] = json_data.get("body") or json_data

    v: Dict[str, Any] = {
        "timestamp":        body.get("timestamp"),
        "camera_id":        body.get("camera_id"),
        "camera_name":      body.get("camera_name"),
        "location":         body.get("location") or "",
        "vehicle_type":     body.get("vehicle_type"),
        "license_plate":    body.get("license_plate"),
        "violation_tags":   body.get("violation_tags") or [],
        "track_id":         body.get("track_id"),
        "speed":            body.get("speed"),
        "full_frame_b64":   strip_data_url(body.get("images", {}).get("full_frame")),
        "vehicle_crop_b64": strip_data_url(body.get("images", {}).get("vehicle_crop")),
        "plate_crop_b64":   strip_data_url(body.get("images", {}).get("plate_crop")),
    }

    # ====== Format dữ liệu hiển thị ======

    # Vị trí
    location_raw = v["location"] or ""
    location_display = location_raw.strip() or UNKNOWN

    # Thời gian
    raw_ts = v["timestamp"]
    time_display = UNKNOWN
    footer_time = ""

    if isinstance(raw_ts, str):
        try:
            ts_norm = raw_ts.replace("Z", "+00:00") if "Z" in raw_ts else raw_ts
            dt = datetime.fromisoformat(ts_norm)
            time_display = dt.strftime("%d/%m/%Y %H:%M:%S")
            footer_time = datetime.now().strftime("Hôm nay lúc %H:%M")
        except Exception:
            time_display = raw_ts or UNKNOWN
    elif raw_ts is not None:
        time_display = str(raw_ts)
    else:
        time_display = UNKNOWN

    # Biển số
    plate_raw = v["license_plate"]
    if plate_raw is None or not str(plate_raw).strip():
        plate_display = UNKNOWN
    else:
        plate_display = str(plate_raw).strip()

    # Loại xe
    vtype_raw = v["vehicle_type"]
    if vtype_raw is None:
        vtype_display = UNKNOWN
    else:
        vtype_raw_str = str(vtype_raw)
        vehicle_map = {
            "motorcycle": "🏍️ Xe máy",
            "car":        "🚗 Ô tô",
            "truck":      "🚚 Xe tải",
            "bus":        "🚌 Xe buýt"
        }
        vtype_display = vehicle_map.get(vtype_raw_str, vtype_raw_str.capitalize())

    # Tốc độ – xử lý cả trường hợp "jsnull", "null", rỗng,...
    speed_raw = v["speed"]
    if speed_raw is None:
        speed_display = UNKNOWN
    else:
        s = str(speed_raw).strip()
        if not s or s.lower() in ("jsnull", "null", "none", "nan"):
            speed_display = UNKNOWN
        else:
            speed_display = f"{s} km/h"

    # Vi phạm
    tag_names = v["violation_tags"] or []
    violations: List[str] = []
    for t in tag_names:
        label = TAG_LABELS.get(t, t.replace("_", " ").capitalize())
        violations.append(label)

    if violations:
        violation_text = "\n".join(violations)
    else:
        violation_text = UNKNOWN

    # Track ID
    track_raw = v["track_id"]
    track_display = str(track_raw) if track_raw is not None else UNKNOWN

    # ====== Tạo EMBED ======
    footer_text = f"ID: {track_display}"
    if footer_time:
        footer_text += f" • {footer_time}"

    discord_message = {
        "title": "🚨 XÁC NHẬN VI PHẠM GIAO THÔNG",
        "color": 15158332,
        "fields": [
            {
                "name": "📍 Vị trí",
                "value": location_display,
                "inline": True,
            },
            {
                "name": "🕒 Thời gian",
                "value": time_display,
                "inline": True,
            },
            {
                "name": "🚗 Phương tiện",
                "value": vtype_display,
                "inline": True,
            },
            {
                "name": "🔢 Biển số",
                "value": plate_display,
                "inline": True,
            },
            {
                "name": "🏁 Tốc độ",
                "value": speed_display,
                "inline": True,
            },
            {
                "name": "⚠️ Loại vi phạm",
                "value": violation_text,
                "inline": False,
            },
        ],
        "footer": {
            "text": footer_text,
        },
    }

    out.append({
        "json": {
            **v,
            "discord_message": discord_message,
        }
    })

return out
